head.script:
scwin.screenId = "jldfil05016";

///////// 1. 변수 및 선언 영역 /////////

// as-is 공용 상수 — 셸이 js/elw.js 를 싣지 않아 화면에 선언한다(KRX 합의 대상).
scwin.LD_MKT_TP_CD = '1';

scwin.NEWSEL = 4;

scwin.BZ_NEWLST = 1;

scwin.CD_NEWLST = '003';

scwin.SELECT = 2;

scwin.form = null;


///////// 2. 초기화 영역 /////////

// 조건 평가 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_conds
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_conds = async function () {
    const binds = [{ id: "btn_contnInputPopup", fn: function(){ return ((dma_page.get("total") ?? (() => { throw new Error("unresolved:" + "page.total"); })()) != 0); } }, { id: "btn_batchElwSubmit", fn: function(){ return ((dma_page.get("total") ?? (() => { throw new Error("unresolved:" + "page.total"); })()) != 0); } }];
    let applied = 0;
    for (let i = 0; i < binds.length; i++) {
        const b = binds[i];
        try {
            const ok = !!b.fn();
            const comp = $c.util.getComponent(b.id);
            if (comp && comp.setStyle) { comp.setStyle("display", ok ? "" : "none"); }
            else if (comp) { if (ok) { if (comp.show) { comp.show(); } } else if (comp.hide) { comp.hide(); } }
            if (ok && b.grids) {
                for (let gi = 0; gi < b.grids.length; gi++) {
                    const gc = $c.util.getComponent(b.grids[gi]);
                    if (gc && gc.refreshGridView) { gc.refreshGridView(); }
                }
            }
            applied++;
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); }
    }
    return applied;
};

// dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_rowCopy
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "__rb0", fn: function () { return "전체 " + String(dma_page.get("total")) + "건 (" + String(dma_page.get("currentPage")) + "/" + String(dma_page.get("pageCount")) + " 페이지) "; } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { console.warn("[sdd] 행 복사 대상 부재: " + it.childId); continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

/**
 * @method
 * @name scwin.init_pageBody
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_pageBody = function () {
    try {
        /* sdd-asis-lifecycle:begin onpageload — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        scwin.form = (document.prelistPageForm || { elements: [] });
        $c.util.getComponent("dma_ElwMstReq").set("bzCd", scwin.BZ_NEWLST);
        $c.util.getComponent("dma_ElwMstReq").set("listBzTpCd", scwin.CD_NEWLST);
        $c.util.getComponent("dma_ElwMstReq").set("spotIsuTrdMktTpCd", scwin.LD_MKT_TP_CD);
        $("#ipt_checkAll").click(function() {
                if ($(this).is(":checked")) {
                    $("input:checkbox[name='checkForBatch']").attr("checked", true);
                } else {
                    $("input:checkbox[name='checkForBatch']").attr("checked", false);
                }
        });
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil05016.onpageload' }); }
};

// [A] 초기 목록 미해결 — 자기 목록을 채우는 tx 가 3개다(tx_fn_ElwMst, tx_fn_ElwDel, tx_fn_batchElwSubmitPop) — 어느 것이 «열자마자» 인지 정할 근거가 없다


// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_rowCopy();
        await scwin.init_conds();
        scwin.init_pageBody();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldfil05016.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @event
 * @name scwin.slc_currentPageSize_onchange
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.slc_currentPageSize_onchange = async function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin slc_currentPageSize_onchange — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        await scwin.search();
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil05016.slc_currentPageSize_onchange' }); }
};

/**
 * @event
 * @name scwin.grd_pageList_oncellclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param rowIndex columnIndex columnId
 * @returns
 * @hidden N
*/
scwin.grd_pageList_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_pageList');
        if (!dl) { console.error('[sdd] 행 동작 대상 목록 없음: dlt_pageList'); return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        if (columnId === "__rowAct") { if (r["bzProcsNo"] != null && r["bzProcsNo"] !== '') { if (typeof scwin.elwDel === 'function') { await scwin.elwDel(r["bzProcsNo"], r["listProcsStatCd"]); } else { console.error('[sdd] 행 동작 미정의: scwin.elwDel (열 삭제)'); await $c.win.alert('이 행 동작을 아직 정하지 못했습니다(전환 미완) — scwin.elwDel'); } return; } return; } if (typeof scwin.elwMst === 'function') { await scwin.elwMst(r["isuCd"], r["bzProcsNo"], r["listProcsStatCd"], r["listProcsRsn"]); } else { console.error('[sdd] 행 동작 미정의: scwin.elwMst (열 ?)'); await $c.win.alert('이 행 동작을 아직 정하지 못했습니다(전환 미완) — scwin.elwMst'); } return;
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_pageList.oncellclick' });
    }
};

/**
 * @event
 * @name scwin.btn_contnInputPopup_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.btn_contnInputPopup_onclick = async function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin btn_contnInputPopup_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        await scwin.contnInputPopup()
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil05016.btn_contnInputPopup_onclick' }); }
};

/**
 * @event
 * @name scwin.btn_batchElwSubmit_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.btn_batchElwSubmit_onclick = async function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin btn_batchElwSubmit_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        await scwin.fn_batchElwSubmit()
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil05016.btn_batchElwSubmit_onclick' }); }
};


///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name scwin.tx_fn_ElwMst
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_ElwMst = async function () {
    const sbmOptions = {
        id: "tx_fn_ElwMst",
        method: "post",
        action: "/list/elw.do",
        ref: "dma_ElwMstReq",
        target: "dlt_pageList=body.content",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldfil05016.tx_fn_ElwMst" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};

/**
 * @method
 * @name scwin.tx_fn_ElwDel
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_ElwDel = async function () {
    const sbmOptions = {
        id: "tx_fn_ElwDel",
        method: "post",
        action: "/list/elwPage.do",
        ref: "dma_ElwDelReq",
        target: "dlt_pageList=body.content",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldfil05016.tx_fn_ElwDel" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};

/**
 * @method
 * @name scwin.tx_fn_batchElwSubmitPop
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_batchElwSubmitPop = async function () {
    const sbmOptions = {
        id: "tx_fn_batchElwSubmitPop",
        method: "post",
        action: "/list/elwPage.do",
        ref: "dma_batchElwSubmitPopReq",
        target: "dlt_pageList=body.content",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldfil05016.tx_fn_batchElwSubmitPop" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};


///////// 5. 일반/업무 함수 영역 /////////

/**
 * @event
 * @name scwin.grd_pageList_fillAct
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.grd_pageList_fillAct = async function () {
    try {
        const dl = $c.util.getComponent('dlt_pageList');
        if (!dl || !dl.getTotalRow) { return; }
        for (let i = 0; i < dl.getTotalRow(); i++) {
            const r = dl.getRowJSON(i);
            let v = '-';
            if (r) { if (r["bzProcsNo"] != null && r["bzProcsNo"] !== '') { v = "삭제"; } }
            dl.setCellData(i, "__rowAct", v);
        }
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_pageList.fillAct' });
    }
};

/**
 * @method
 * @name scwin.elwMst
 * @author Inswave
 * @date 2026. 09. 29
 * @param isuCd bzProcsNo listProcsStatCd listProcsRsn
 * @returns
 * @hidden N
*/
scwin.elwMst = async function (isuCd, bzProcsNo, listProcsStatCd, listProcsRsn) {
    /* sdd-asis-lifecycle:begin fn_ElwMst — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (bzProcsNo !== "") {
        $c.util.getComponent("dma_ElwMstReq").set("transKind", scwin.SELECT);
    } else {
        $c.util.getComponent("dma_ElwMstReq").set("transKind", scwin.NEWSEL);
    }
    fn_clearTransTbl();
    fn_setMainPage();
    $c.util.getComponent('dma_ElwMstReq').set('isuCd', isuCd);
    $c.util.getComponent('dma_ElwMstReq').set('bzProcsNo', bzProcsNo);
    if (listProcsStatCd === '03') {
        $c.util.getComponent('dma_ElwMstReq').set('listProcsStatCd', listProcsStatCd);
        $c.util.getComponent('dma_ElwMstReq').set('nowPage', listProcsRsn);
        $c.util.getComponent('dma_ElwMstReq').set('billLstSaveStatCd', '4');
        goNextPage(listProcsRsn);
    } else {
        scwin.form.action = '/list/elw.do';
        $c.util.getComponent('dma_ElwMstReq').set('method', 'searchElw');
        await scwin.tx_fn_ElwMst();
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.elwDel
 * @author Inswave
 * @date 2026. 09. 29
 * @param bzProcsNo listProcsStatCd
 * @returns
 * @hidden N
*/
scwin.elwDel = async function (bzProcsNo, listProcsStatCd) {
    /* sdd-asis-lifecycle:begin fn_ElwDel — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.util.getComponent('dma_ElwMstReq').set('bzProcsNo', bzProcsNo);
    if (listProcsStatCd === '03') {
        await $c.win.alert('반송인 경우 삭제할 수 없습니다.');
        return;
    }
    if (!$c.lc.fn_isProcess('D')) {
        return;
    }
    scwin.form.action = '/list/elwPage.do';
    $c.util.getComponent('dma_ElwMstReq').set('method', 'elwPageDelete');
    await scwin.tx_fn_ElwDel();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.search
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.search = async function () {
    /* sdd-asis-lifecycle:begin fn_Search — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.util.getComponent('dma_ElwMstReq').set('method', 'elwPageSearch');
    await moveUrl('/list/elwPage.do', {});
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.contnInputPopup
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.contnInputPopup = async function () {
    /* sdd-asis-lifecycle:begin fn_contnInputPopup — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const url = '/jldfil05011/jldfil05011.xml';
    if (isNotAdmin()) {
        if (!$("[name='checkForBatch']").is(':checked')) {
            await $c.win.alert('선택된 항목이 없습니다.');
            return;
        }
        await $c.win.openPopup((function (__u) { var __s = String(__u == null ? "" : __u); if (!/\.xml(\?|#|$)/.test(__s)) { throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + __s, unresolved: "nav:" + __s }; } return __u; })(url), { id: "contnPopup", scrollbars: false, resizable: false, width: "640", height: "240", type: "pageFramePopup" }, { method: "elwNewListContnPopup" });
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.fn_batchElwSubmit
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.fn_batchElwSubmit = async function () {
    /* sdd-asis-lifecycle:begin fn_batchElwSubmit — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const selObj = $c.util.getComponent('ipt_checkForBatch');
    const obj = scwin.form.chkMngRefContn;
    const chkVal = false;
    for (let i = 0; i < selObj.length; i++) {
        if (selObj[i].checked && obj[i].value === '') {
            await $c.win.alert('[경영상 중대한 사실 발생 여부]를 입력한 종목만 선택제출 할 수 있습니다. 입력이 된 종목만 다시 선택 해주세요.');
            return;
        }
    }
    batchElwSubmit();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.batchElwSubmitPop
 * @author Inswave
 * @date 2026. 09. 29
 * @param strContn
 * @returns
 * @hidden N
*/
scwin.batchElwSubmitPop = async function (strContn) {
    /* sdd-asis-lifecycle:begin fn_batchElwSubmitPop — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (strContn !== '') {
        $c.util.getComponent('dma_ElwMstReq').set('mngRefContn', strContn);
    }
    scwin.form.action = '/list/elwPage.do';
    $c.util.getComponent('dma_ElwMstReq').set('method', 'batchElwSubmit');
    await scwin.tx_fn_batchElwSubmitPop();
    /* sdd-asis-lifecycle:end */
};



/**
 * @event
 * @name scwin.krxpage_pagenavigator_82_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param index
 * @returns
 * @hidden N
*/
scwin.krxpage_pagenavigator_82_onclick = function (index) { const pi = (index && typeof index === 'object') ? index.newSelectedIndex : index; try { $c.util.getComponent('dma_ElwMstReq').set('pageIndex', pi); } catch (e) { $c.exception.handleError(e, { notify: 'none', context: 'krxpage_pagenavigator_82.page' }); } scwin.search(); };
